insert into public.events(id,config) values(1,'{"name":"MIND RIZZ","logo_name":"MIND RIZZ","logo_url":"","hero_image":"","favicon":"","banner":"","browser_title":"MIND RIZZ | Think. Play. Conquer.","tagline":"THINK. PLAY. CONQUER.","college":"COLLEGE TECH FEST 2026","description":"A little logic. A little instinct. A whole lot of mind power. Take on the ultimate offline challenge with your partner in think.","edition":"2026","venue":"Main Auditorium","starts_at":"2026-10-25T04:30:00Z","timezone":"Asia/Kolkata","countdown":true,"after_countdown":"EVENT IS LIVE","register_label":"Register your team","explore_label":"Explore the challenge","registration_open":true,"opens_at":"2026-09-01T00:00:00Z","deadline":"2026-10-20T18:29:00Z","capacity":100,"checkin_open":"2026-10-25T03:30:00Z","checkin_close":"2026-10-25T04:15:00Z","level_starts":["2026-10-25T04:30:00Z","2026-10-25T05:30:00Z","2026-10-25T06:30:00Z"],"results_time":"2026-10-25T09:30:00Z","published":false,"leaderboard":"admin","tiebreak":[3,2,1],"about_title":"Not just smart.\nThink different.","about":"MIND RIZZ is where quick thinking meets a competitive spirit. An offline intellectual challenge built to test your logic, creativity, decision-making, and ability to stay cool under pressure. Two minds. Three levels. One unforgettable experience.","objectives":[{"title":"Think logically","description":"","icon":"Sparkles","visible":true},{"title":"Solve creatively","description":"","icon":"Sparkles","visible":true},{"title":"Decide confidently","description":"","icon":"Sparkles","visible":true},{"title":"Work together","description":"","icon":"Sparkles","visible":true},{"title":"Stay sharp under pressure","description":"","icon":"Sparkles","visible":true},{"title":"Compete with curiosity","description":"","icon":"Sparkles","visible":true}],"benefits":[{"title":"THINK","description":"Find the pattern others miss.","icon":"Brain","visible":true},{"title":"CHALLENGE","description":"Your comfort zone ends here.","icon":"Zap","visible":true},{"title":"WIN","description":"Earn your place on the podium.","icon":"Trophy","visible":true},{"title":"STRATEGY","description":"Every decision makes a difference.","icon":"Target","visible":true},{"title":"SPEED","description":"Make every second count.","icon":"Timer","visible":true},{"title":"EXPERIENCE","description":"A story worth telling later.","icon":"Users","visible":true}],"steps":[{"title":"Register","description":"Create an account and a two-person team.","icon":"Sparkles","visible":true},{"title":"Check in","description":"Bring your team QR pass to the venue.","icon":"Sparkles","visible":true},{"title":"Level 1","description":"Warm up with Puzzle Rush.","icon":"Sparkles","visible":true},{"title":"Level 2","description":"Go deeper in Logic Battle.","icon":"Sparkles","visible":true},{"title":"Level 3","description":"Take on Mind Master.","icon":"Sparkles","visible":true},{"title":"Final score","description":"Every point adds up.","icon":"Sparkles","visible":true},{"title":"Results","description":"See where your team stands.","icon":"Sparkles","visible":true},{"title":"Winners","description":"Celebrate the sharpest minds.","icon":"Sparkles","visible":true}],"rules":[{"title":"Eligibility","description":"Open to eligible college students. Provide valid student information and register before the deadline.","icon":"Sparkles","visible":true},{"title":"General rules","description":"Follow organizer instructions. Arrive before check-in closes. Challenges take place offline.","icon":"Sparkles","visible":true},{"title":"Team rules","description":"Exactly two members per team. A participant may join only one team. Member changes require admin approval.","icon":"Sparkles","visible":true},{"title":"Level 1 rules","description":"Read carefully. Submit before the timer ends. No outside assistance.","icon":"Sparkles","visible":true},{"title":"Level 2 rules","description":"Discuss only with your teammate. Follow the instructions provided at the venue.","icon":"Sparkles","visible":true},{"title":"Level 3 rules","description":"No unauthorized materials or devices. Organizer decisions on challenge answers are final.","icon":"Sparkles","visible":true},{"title":"Scoring","description":"Your final score is the sum of all three level scores.","icon":"Sparkles","visible":true},{"title":"Disqualification","description":"Cheating, unauthorized assistance, misconduct, or rule violations can result in disqualification.","icon":"Sparkles","visible":true},{"title":"Winner selection","description":"Highest total wins. Ties use Level 3, then Level 2, then Level 1. Remaining ties are resolved by organizers before publication.","icon":"Sparkles","visible":true}],"nav":[{"title":"Home","description":"home","icon":"Sparkles","visible":true},{"title":"About","description":"about","icon":"Sparkles","visible":true},{"title":"Levels","description":"levels","icon":"Sparkles","visible":true},{"title":"Rules","description":"rules","icon":"Sparkles","visible":true}],"theme":"dark","colors":{"background":"#090909","card":"#131313","text":"#eeeeee","muted":"#959595","border":"#292929","primary":"#ffffff","secondary":"#a3a3a3","heading":"#ffffff","button":"#ffffff","button-text":"#090909","hover":"#d2d2d2"},"heading_font":"Arial","body_font":"Arial","radius":10,"button_hover":"lift","button_style":"solid","button_size":"normal"}'::jsonb) on conflict(id) do nothing;
insert into public.levels(id,data) values(1,'{"id":1,"name":"Puzzle Rush","short":"Find your rhythm. Crack the code.","description":"A fast-paced warm-up of patterns, puzzles, and lateral thinking. Spot the details and trust your instincts.","instructions":"Read each question carefully.\nWork with your teammate.\nSubmit answers before time expires.","rules":"No outside assistance. Follow organizer instructions.","minutes":15,"maximum":100,"difficulty":"Easy","status":"upcoming","remaining":900,"started_at":null,"visible":true}'::jsonb) on conflict(id) do nothing;
insert into public.levels(id,data) values(2,'{"id":2,"name":"Logic Battle","short":"Less guessing. More game plan.","description":"Connect the dots through multi-step reasoning challenges. A cool head and a clear strategy make all the difference.","instructions":"Listen to the briefing.\nDiscuss only with your teammate.\nSubmit within the time limit.","rules":"No unauthorized devices or assistance.","minutes":20,"maximum":100,"difficulty":"Medium","status":"upcoming","remaining":1200,"started_at":null,"visible":true}'::jsonb) on conflict(id) do nothing;
insert into public.levels(id,data) values(3,'{"id":3,"name":"Mind Master","short":"The final test of your thinking.","description":"Complex challenges where speed, creativity, and precision collide. This is where the sharpest minds rise.","instructions":"Read all instructions.\nAllocate your time carefully.\nSubmit final answers to the organizer.","rules":"All general event rules apply.","minutes":25,"maximum":100,"difficulty":"Hard","status":"upcoming","remaining":1500,"started_at":null,"visible":true}'::jsonb) on conflict(id) do nothing;
